// ==========================================
// 辅助公共方法：洗牌与动态生成填空词库
// ==========================================
window.shuffleArray = function(arr) {
  const array = [...arr];
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
  return array;
};

window.generateDynamicAnswerPool = function(selectedQuestions) {
  const answerSet = new Set();
  selectedQuestions.forEach(q => {
    if (q.type === "fill" && q.blanks) {
      q.blanks.forEach(b => {
        const primaryAns = b.ans.split("|")[0].trim();
        if (primaryAns) answerSet.add(primaryAns);
      });
    }
  });

  const distractors = [
    "五千", "两条鱼", "十二篮", "摩西", "以利亚", "大卫", "伯赛大", "三天半", 
    "十两银子", "葡萄树", "箱子", "桌子", "二百", "按手", "睡着了", "二万", 
    "迦百农", "岸上", "撒玛利亚", "鞋", "三座棚", "小孩子", "一杯水", "大磨石", 
    "用人", "绊倒", "彼得", "四更天", "两件褂子", "革尼撒勒", "马利亚", "希罗底"
  ];
  const shuffledDistractors = window.shuffleArray(distractors);
  for (let i = 0; i < shuffledDistractors.length && answerSet.size < 22; i++) {
    answerSet.add(shuffledDistractors[i]);
  }

  return window.shuffleArray(Array.from(answerSet));
};
